    help: () => say('Commands: RECORD, OPS, PROFILE, UPLINK, LOCATE <CP|HK|ND>, OPEN <name>, LIST, FILTER <xr|tools|client|engineering|all>, WHOAMI, TIME, SOUND, PLAIN, LOGOUT, CLEAR.'),
